 async function fill(values){await evalJS(`(()=>{for(const [id,value] of Object.entries(${JSON.stringify(values)})){const n=document.getElementById(id);if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('input',{bubbles:true}));}})()`);}
 async function clearRequests(){await waitFor(()=>evalJS("[...document.querySelectorAll('#operation-list button')].filter(b=>b.textContent==='Discard retained request').every(b=>!b.disabled)"));await evalJS(`(()=>{const key='kavern-ui-requests-v1';const values=JSON.parse(sessionStorage.getItem(key)||'[]');if(values.some(v=>!v.resolved))throw new Error('Unresolved request');for(const b of [...document.querySelectorAll('button')])if(b.textContent==='Discard retained request')b.click();})()`);}
 async function submit(){await evalJS("document.querySelector('#edit-form').requestSubmit()");await waitFor(()=>evalJS("(()=>{const last=[...document.querySelectorAll('#operation-list .operation')].at(-1);return last?.querySelector('p').textContent.startsWith('Saved revision')&&[...last.querySelectorAll('button')].some(b=>b.textContent==='Discard retained request'&&!b.disabled);})()"));}
 async function select(id){await evalJS(`(()=>{const b=[...document.querySelectorAll('.device-card')].find(b=>b.querySelector('small').textContent===${JSON.stringify(id)});if(!b)throw new Error('Missing device');b.click();})()`);await waitFor(()=>evalJS(`document.querySelector('#detail .identity')?.textContent.includes(${JSON.stringify(id+' ·')})`));}
