 check((await (await fetch(new URL('/start-agents',attacker))).json()).started===2,'Two agents not started');
 phase='native automatic sync and TCP';await select('alpha');await ready();await probe('alpha','first:');await select('beta');await ready();await probe('beta','first:');summary.createAutosyncTCP=true;check((await (await fetch(new URL('/hidden-tunnels',attacker))).json()).saved,'Hidden disabled fixture not saved');await select('alpha');await ready();
 phase='target edit with other-device isolation';await select('alpha');await action('Edit tunnel');await fill({'tunnel-target':info.target2});await screenshot('w2-edit-tunnel.png');await submit();await clearRequests();await ready();await probe('alpha','second:');await probe('beta','first:');summary.editIsolation=true;
 phase='tunnel disable and listener failure';await action('Edit tunnel');await fill({'tunnel-enabled':false});await submit();await clearRequests();await waitFor(()=>evalJS("document.querySelector('#detail .tunnel .pill')?.textContent==='Disabled'"));check(!(await fetch(new URL('/probe?device=alpha&prefix=second:',attacker))).ok,'Disabled tunnel admitted TCP');await action('Edit tunnel');await fill({'tunnel-enabled':true});await submit();await clearRequests();await ready();await probe('alpha','second:');summary.tunnelDisableEnable=true;
 await action('Edit tunnel');await fill({'tunnel-listener':info.target1});await submit();await waitFor(()=>evalJS("document.querySelector('#detail .device-heading .pill')?.textContent==='Listener failed'"));await screenshot('w2-saved-bind-failure.png');await clearRequests();await probe('beta','first:');await action('Edit tunnel');await fill({'tunnel-listener':info.listener1});await submit();await clearRequests();await ready();await probe('alpha','second:');summary.savedListenerFailure=true;
 phase='stale CAS draft retention';await action('Edit device');await fill({'device-name':'My retained draft'});await fetch(new URL('/concurrent-edit',attacker));await evalJS("document.querySelector('#edit-form').requestSubmit()");await waitFor(()=>evalJS("document.querySelector('#editor').textContent.includes('revision_conflict')"));check(await evalJS("document.querySelector('#device-name').value==='My retained draft'"),'Conflict erased draft');await screenshot('w2-conflict.png');await action('Review current configuration');await waitFor(()=>evalJS("document.querySelector('#editor pre')?.textContent.includes('Concurrent authoritative name')"));await action('Reload editor from current state');check(await evalJS("document.querySelector('#device-name').value==='Concurrent authoritative name'"),'Explicit reload not current');await action('Cancel');await clearRequests();summary.staleCAS=true;
