 phase='lost response exact recovery';await action('Edit device');await fill({'device-name':'Saved despite response loss'});await evalJS(`(()=>{globalThis.savedFetch=fetch;let once=true;globalThis.fetch=async(...args)=>{const response=await savedFetch(...args);if(once&&String(args[0]).endsWith('api/mutations')){once=false;throw new TypeError('Synthetic response lost');}return response;};document.querySelector('#edit-form').requestSubmit();})()`);await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('Outcome unconfirmed')"));check(await evalJS("document.querySelector('#edit-form button[type=submit]').disabled"),'Unknown save allowed a new operation');const retainedBefore=await evalJS("sessionStorage.getItem('kavern-ui-requests-v1')");await evalJS("document.querySelector('#edit-form').requestSubmit()");await new Promise(r=>setTimeout(r,100));check(await evalJS(`sessionStorage.getItem('kavern-ui-requests-v1')===${JSON.stringify(retainedBefore)}`),'Repeated save minted another operation');summary.unconfirmedNewSaveBlocked=true;
 await screenshot('w2-unconfirmed.png');const original=await evalJS("JSON.parse(sessionStorage.getItem('kavern-ui-requests-v1'))[0].request");await evalJS('globalThis.fetch=globalThis.savedFetch');await action('Look up original receipt');await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('confirmed by original receipt')"));check(await evalJS(`JSON.parse(sessionStorage.getItem('kavern-ui-requests-v1'))[0].request.operation_id===${JSON.stringify(original.operation_id)}`),'Recovery changed operation');await clearRequests();await action('Cancel');summary.responseLossRecovery=true;
 phase='uncertainty feedback and explicit recovery';await select('alpha');await action('Edit device');await fill({'device-name':'Recovered durable state'});await evalJS(`(()=>{globalThis.savedFetch=fetch;let once=true;globalThis.fixtureUncertain=false;globalThis.fetch=async(...args)=>{if(fixtureUncertain&&String(args[0]).endsWith('api/status'))return new Response(JSON.stringify({health:'commit_uncertain',cleanup_pending:true}),{status:200,headers:{'Content-Type':'application/json'}});const response=await savedFetch(...args);if(once&&String(args[0]).endsWith('api/mutations')){once=false;fixtureUncertain=true;return new Response(JSON.stringify({code:'commit_uncertain',outcome:'unconfirmed'}),{status:502,headers:{'Content-Type':'application/json'}});}if(String(args[0]).endsWith('api/recover'))fixtureUncertain=false;return response;};document.querySelector('#edit-form').requestSubmit();})()`);await waitFor(()=>evalJS("document.querySelector('#health').textContent==='Durability uncertain'"));check(await evalJS("document.querySelector('#edit-fields').disabled&&document.querySelector('#detail h2').textContent==='Status unavailable'"),'Uncertainty did not fence editing and readiness');await screenshot('w2-commit-uncertain.png');await action('Recover daemon state');await waitFor(()=>evalJS("document.querySelector('#health').textContent==='Daemon running'"));await action('Look up original receipt');await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('confirmed by original receipt')"));await clearRequests();await action('Cancel');await evalJS('globalThis.fetch=globalThis.savedFetch');summary.syntheticUncertaintyRecovery=true;
 phase='daemon restart and reconnect';await fetch(new URL('/restart',attacker));await evalJS("document.querySelector('#refresh').click()");await select('alpha');await ready();await probe('alpha','second:');await select('beta');await ready();await probe('beta','first:');summary.restartReconnect=true;check((await (await fetch(new URL('/preserved',attacker))).json()).preserved,'Complete hidden/disabled tunnel set or policy lost');summary.completeConfigurationPreserved=true;
 phase='session expiry exact import';await select('alpha');await action('Edit device');await fill({'device-name':'Saved across expired browser session'});await evalJS(`(()=>{globalThis.savedFetch=fetch;let once=true;globalThis.fetch=async(...args)=>{const response=await savedFetch(...args);if(once&&String(args[0]).endsWith('api/mutations')){once=false;return new Response(JSON.stringify({code:'session_expired'}),{status:401,headers:{'Content-Type':'application/json'}});}return response;};document.querySelector('#edit-form').requestSubmit();})()`);await waitFor(()=>evalJS("document.querySelector('#health').textContent==='Session expired'"));await action('Export original request');const envelope=await evalJS("document.querySelector('#request-envelope').value");check(JSON.parse(envelope).window.epoch,'Original window lost on expiry');const newBridge=await (await fetch(new URL('/new-bridge',attacker))).json();await send('Page.navigate',{url:newBridge.launch});await waitFor(()=>evalJS("document.querySelector('#health').textContent==='Daemon running'"));await fill({'request-envelope':envelope});await action('Import for lookup');await action('Look up original receipt');await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('confirmed by original receipt')"));await evalJS("document.querySelector('#operations').scrollIntoView({block:'start'})");await screenshot('w2-recovered.png');await clearRequests();summary.expiryImportRecovery=true;const tampered=JSON.parse(envelope);tampered.configuration.Device.Name='Changed imported content';await fill({'request-envelope':JSON.stringify(tampered)});await action('Import for lookup');await action('Look up original receipt');await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('operation_reuse')"));check(await evalJS("!document.querySelector('#operation-list').textContent.includes('confirmed by original receipt')"),'Altered import falsely confirmed');await screenshot('w2-tampered-request.png');await evalJS("globalThis.confirm=()=>true");await action('Discard retained request');summary.alteredImportRejected=true;
 phase='expired unknown receipt';check((await (await fetch(new URL('/evict-receipts',attacker))).json()).evicted,'Receipt eviction fixture failed');const unknown=JSON.parse(envelope);await fill({'request-envelope':JSON.stringify(unknown)});await action('Import for lookup');await action('Look up original receipt');await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('previous outcome remains unknown')"));await evalJS("document.querySelector('#operations').scrollIntoView({block:'start'})");await screenshot('w2-expired-unknown.png');summary.expiredUnknown=true;
 phase='review rejected retry preserves original unknown outcome';
 await action('Retry exact original request');
 await waitFor(()=>evalJS("document.querySelector('#operation-list').textContent.includes('Rejected:')"));
 const originalResolution=await evalJS("JSON.parse(sessionStorage.getItem('kavern-ui-requests-v1'))[0].resolved");
 check(originalResolution!==true,'Rejected retry incorrectly resolved the original evicted/unknown operation');

